    const a = 2 * this['re'];
    const b = 2 * this['im'];
    const d = cosh(a) + Math.cos(b);

    return new Complex(
      sinh(a) / d,
      Math.sin(b) / d);
  }

function () {

    let a = this['re'];
    let b = this['im'];
    let ret = "";

    if (this['isNaN']()) {
      return 'NaN';
    }

    if (this['isInfinite']()) {
      return 'Infinity';
    }

    if (Math.abs(a) < Complex['EPSILON']) {
      a = 0;
    }

    if (Math.abs(b) < Complex['EPSILON']) {
      b = 0;
    }

    // If is real number
    if (b === 0) {
      return ret + a;
    }

    if (a !== 0) {
      ret += a;
      ret += " ";
      if (b < 0) {
        b = -b;
        ret += "-";
      } else {
        ret += "+";
      }
      ret += " ";
    } else if (b < 0) {
      b = -b;
      ret += "-";
    }

    if (1 !== b) { // b is the absolute imaginary part
      ret += b;
    }
    return ret + "i";
  }

function () {

    return [this['re'], this['im']];
  }

function () {

    if (this['im'] === 0) {
      return this['re'];
    }
    return null;
  }

function Complex(a, b) {

  if (!(this instanceof Complex)) {
    return new Complex(a, b);
  }

  const z = parse(a, b);

  this['re'] = z['re'];
  this['im'] = z['im'];
}

function getAllTimezones(options = {}) {
	if (totalTimezones !== memoizedTimezones) for (const name of Object.keys(data_default.timezones)) getTimezone(name);
	return deliverTimezones(timezones, options);
}

function getCountriesForTimezone(tzName, options = {}) {
	return ((getTimezone(tzName) || {}).countries || []).map((c) => getCountry(c, options));
}

function getCountry(id, options = {}) {
	if (!countries[id]) memoizeCountry(buildCountry(data_default, id));
	return deliverCountry(countries[id], options);
}

function getCountryForTimezone(tzName, options = {}) {
	const [main] = getCountriesForTimezone(tzName, options);
	return main || null;
}

function getTimezone(name) {
	if (!timezones[name]) memoizeTimezone(buildTimezone(data_default, name));
	return timezones[name] ? { ...timezones[name] } : null;
}

function getTimezonesForCountry(countryId, options = {}) {
	const country = getCountry(countryId, options);
	if (!country) return null;
	return (country.timezones || []).map((timezone) => getTimezone(timezone));
}

function getAllCountries(options = {}) {
	return Object.keys(data_default.countries).reduce((previous, id) => {
		return Object.assign(previous, { [id]: getCountry(id, options) });
	}, {});
}

function getAllTimezones(options = {}) {
	if (totalTimezones !== memoizedTimezones) for (const name of Object.keys(data_default.timezones)) getTimezone(name);
	return deliverTimezones(timezones, options);
}

function getCountry(id, options = {}) {
	if (!countries[id]) memoizeCountry(buildCountry(data_default, id));
	return deliverCountry(countries[id], options);
}

class GeoPoint {
    /**
     *
     * @param latitude
     * @param longitude
     */
    constructor(latitude, longitude) {
        if (typeof latitude !== 'number' || typeof longitude !== 'number') {
            throw new RangeError('Bad geo point arguments');
        }
        if (latitude < -90 || latitude > 90) {
            throw new RangeError('bad latitude value');
        }
        if (longitude < -180 || longitude > 180) {
            throw new RangeError('bad longitude value');
        }
        this.latitude = latitude;
        this.longitude = longitude;
    }
    /**
     *
     * @param point {{type: String, coordinates: Array}}
     * @returns {GeoPoint}
     */
    static fromGeoJSON(point) {
        if (!isObject(point)) {
            throw new TypeError('GeoPoint: Argument must be an object');
        }
        if (!point.hasOwnProperty('type') || !point.hasOwnProperty('coordinates')) {
            throw new TypeError('Object must have type and coordinates');
        }
        if (point.type !== 'Point') {
            throw new TypeError('The value of type should be \'Point\'');
        }
        if (!Array.isArray(point.coordinates) || point.coordinates.length !== 2) {
            throw new TypeError('coordinates must be an array and contain 2 elements');
        }
        return this.fromLngLatArray(point.coordinates);
    }
    /**
     *
     * @param object {{latitude: Number, longitude: Number}}
     * @returns {GeoPoint}
     */
    static fromObject(object) {
        if (!isObject(object)) {
            throw new TypeError('GeoPoint: Argument must be an object');
        }
        if (!object.hasOwnProperty('latitude') || !object.hasOwnProperty('longitude')) {
            throw new TypeError('Object must have latitude and longitude');
        }
        return new GeoPoint(object.latitude, object.longitude);
    }
    /**
     *
     * @param point1
     * @param point2
     * @returns {number}
     */
    static calculateDistance(point1, point2) {
        const point1Rad = deg2rad(point1.latitude);
        const point2Rad = deg2rad(point2.latitude);
        const a = deg2rad(point2.longitude) - deg2rad(point1.longitude);
        const b = cos(point1Rad) * cos(point2Rad) * cos(a);
        const c = sin(point1Rad) * sin(point2Rad);
        const r = b + c;
        return acos(r > 1 ? 1 : r) * 6371392.896;
    }
    /**
     *
     * @param point1 {GeoPoint}
     * @param point2 {GeoPoint}
     * @returns {number}
     */
    static calculateBearing(point1, point2) {
        const φ1 = deg2rad(point1.latitude), φ2 = deg2rad(point2.latitude);
        const Δλ = deg2rad(point2.longitude - point1.longitude);
        // see http://mathforum.org/library/drmath/view/55417.html
        const y = sin(Δλ) * cos(φ2);
        const x = cos(φ1) * sin(φ2) - sin(φ1) * cos(φ2) * cos(Δλ);
        const θ = atan2(y, x);
        return (rad2deg(θ) + 360) % 360;
    }
    /**
     *
     * @param coordinate {GeoPoint}
     * @param distance {Number} distance in meters
     * @param bearing {Number} bearing in degrees
     * @returns {GeoPoint}
     */
    static calculateDestination(coordinate, distance, bearing) {
        // sinφ2 = sinφ1⋅cosδ + cosφ1⋅sinδ⋅cosθ
        // tanΔλ = sinθ⋅sinδ⋅cosφ1 / cosδ−sinφ1⋅sinφ2
        // see http://williams.best.vwh.net/avform.htm#LL
        const δ = Number(distance) / radius; // angular distance in radians
        const θ = deg2rad(Number(bearing));
        const φ1 = deg2rad(coordinate.latitude);
        const λ1 = deg2rad(coordinate.longitude);
        const sinφ1 = sin(φ1), cosφ1 = cos(φ1);
        const sinδ = sin(δ), cosδ = cos(δ);
        const sinθ = sin(θ), cosθ = cos(θ);
        const sinφ2 = sinφ1 * cosδ + cosφ1 * sinδ * cosθ;
        const φ2 = asin(sinφ2);
        const y = sinθ * sinδ * cosφ1;
        const x = cosδ - sinφ1 * sinφ2;
        const λ2 = λ1 + atan2(y, x);
        const latitude = rad2deg(φ2);
        const longitude = (rad2deg(λ2) + 540) % 360 - 180; // normalise to −180..+180°
        return new GeoPoint(latitude, longitude);
    }
    /**
     *
     * @param array
     * @returns {GeoPoint}
     */
    static fromLatLngArray(array) {
        return new GeoPoint(array[0], array[1]);
    }
    /**
     *
     * @param array
     * @returns {GeoPoint}
     */
    static fromLngLatArray(array) {
        return new GeoPoint(array[1], array[0]);
    }
    static toTile(coordinate, zoom) {
        // retrieved from: https://wiki.openstreetmap.org/wiki/Slippy_map_tilenames#ECMAScript_.28JavaScript.2FActionScript.2C_etc..29
        const x = Math.floor((coordinate.longitude + 180) / 360 * Math.pow(2, zoom));
        const y = Math.floor((1 - Math.log(Math.tan(coordinate.latitude * Math.PI / 180) + 1 / Math.cos(coordinate.latitude * Math.PI / 180)) / Math.PI) / 2 * Math.pow(2, zoom));
        return { x, y };
    }
    /**
     *
     * @param distance {Number} distance in meters
     * @param bearing {Number} bearing in degrees
     * @returns {GeoPoint} destination point
     */
    calculateDestination(distance, bearing) {
        return GeoPoint.calculateDestination(this, distance, bearing);
    }
    /**
     *
     * @param point {GeoPoint} destination geo point
     * @returns {number} bearing in degrees
     */
    calculateBearing(point) {
        return GeoPoint.calculateBearing(this, point);
    }
    /**
     *
     * @param point {GeoPoint}
     * @returns {number} distance in meters
     */
    calculateDistance(point) {
        return GeoPoint.calculateDistance(this, point);
    }
    /**
     *
     * @returns {string}
     */
    toString() {
        return `${this.latitude},${this.longitude}`;
    }
    /**
     *
     * @returns {{type: string, coordinates: *[]}}
     */
    toGeoJSON() {
        return {
            type: 'Point',
            coordinates: [
                this.longitude,
                this.latitude,
            ],
        };
    }
    /**
     *
     * @returns {{latitude: *, longitude: *}}
     */
    toObject() {
        return {
            latitude: this.latitude,
            longitude: this.longitude,
        };
    }
    /**
     *
     * @returns {*[]}
     */
    toLatLngArray() {
        return [this.latitude, this.longitude];
    }
    /**
     *
     * @returns {*[]}
     */
    toLngLatArray() {
        return [this.longitude, this.latitude];
    }
    toTile(zoom) {
        return GeoPoint.toTile(this, zoom);
    }
    /**
     *
     * https://gis.stackexchange.com/questions/8650/measuring-accuracy-of-latitude-and-longitude
     *       The sign tells us whether we are north or south, east or west on the globe.
     *       A nonzero hundreds digit tells us we're using longitude, not latitude!
     *       The tens digit gives a position to about 1,000 kilometers. It gives us useful information about what continent or ocean we are on.
     *       The units digit (one decimal degree) gives a position up to 111 kilometers (60 nautical miles, about 69 miles). It can tell us roughly what large state or country we are in.
     *       The first decimal place is worth up to 11.1 km: it can distinguish the position of one large city from a neighboring large city.
     *       The second decimal place is worth up to 1.1 km: it can separate one village from the next.
     *       The third decimal place is worth up to 110 m: it can identify a large agricultural field or institutional campus.
